import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"支援的檔案管理員","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/user-guide/file-manager-support.md","filePath":"zh-TW/user-guide/file-manager-support.md","lastUpdated":1785993908000}'),o={name:"zh-TW/user-guide/file-manager-support.md"};function h(n,t,i,s,l,p){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="支援的檔案管理員" tabindex="-1">支援的檔案管理員 <a class="header-anchor" href="#支援的檔案管理員" aria-label="Permalink to &quot;支援的檔案管理員&quot;">​</a></h1><p>Lertaro 不只是能搜尋——它還可以和你正在使用的檔案管理員或對話方塊進行整合。根據目標視窗的不同，整合最多可以提供以下三種能力：</p><ul><li><strong>內嵌搜尋</strong> —— Lertaro 的搜尋框會直接嵌入目標視窗(也就是<a href="./getting-started.html#三種視窗">內嵌視窗</a>)，不用離開它就能搜尋。</li><li><strong>快速導覽</strong> —— 目標視窗會回應<a href="./hotkeys.html#快速導覽-滑鼠">快速導覽的滑鼠觸發方式</a>(按兩下/中鍵，或者內嵌視窗自帶的圖示)，彈出一個包含我的最愛、歷史記錄和捷徑資料夾的串接式選單。</li><li><strong>作用中路徑偵測</strong> —— Lertaro 能識別目標視窗目前開啟的是哪個資料夾，從而把搜尋範圍限定在該資料夾內，並讓複製路徑這類基於相對路徑的動作能正確解析。</li></ul><p>並不是每種整合都同時提供這三種能力——具體見下表。</p><h2 id="內建-無需額外安裝" tabindex="-1">內建(無需額外安裝) <a class="header-anchor" href="#內建-無需額外安裝" aria-label="Permalink to &quot;內建(無需額外安裝)&quot;">​</a></h2><p>以下幾項都隨 Lertaro 的核心擴充外掛一起提供，不需要單獨啟用。</p><table tabindex="0"><thead><tr><th>目標</th><th>內嵌搜尋</th><th>快速導覽</th><th>作用中路徑偵測</th></tr></thead><tbody><tr><td>Windows 檔案總管</td><td>支援</td><td>按兩下或中鍵</td><td>支援</td></tr><tr><td>現代開啟/儲存檔案對話方塊</td><td>支援(這個對話方塊本身就是內嵌視窗)</td><td>中鍵，或左鍵點擊內嵌視窗自帶的圖示</td><td>——</td></tr><tr><td>傳統開啟/儲存檔案對話方塊</td><td>支援</td><td>中鍵，或左鍵點擊內嵌視窗自帶的圖示</td><td>——</td></tr><tr><td>傳統瀏覽資料夾對話方塊</td><td>支援</td><td>中鍵，或左鍵點擊內嵌視窗自帶的圖示</td><td>——</td></tr></tbody></table><p>作用中路徑偵測對這幾個對話方塊本身沒有意義——一旦 Lertaro 已經嵌入對話方塊裡，就不存在另一個「其它視窗」可供它偵測並作為搜尋範圍了。</p><h2 id="可選外掛-設定-→-外掛" tabindex="-1">可選外掛(設定 → 外掛) <a class="header-anchor" href="#可選外掛-設定-→-外掛" aria-label="Permalink to &quot;可選外掛(設定 → 外掛)&quot;">​</a></h2><p>下面每一項都是獨立的外掛。在<a href="./settings/plugins.html">設定 → 外掛</a>裡安裝/啟用，然後在該外掛自己的<strong>設定</strong>對話方塊裡分別開關<strong>啟用內嵌搜尋</strong>和<strong>啟用快速導覽</strong>——兩者預設都是開啟的。</p><table tabindex="0"><thead><tr><th>目標</th><th>內嵌搜尋</th><th>快速導覽</th><th>作用中路徑偵測</th></tr></thead><tbody><tr><td>Directory Opus</td><td>支援</td><td>在檔案清單區域點擊中鍵</td><td>支援</td></tr><tr><td>Files</td><td>支援</td><td>在檔案清單區域點擊中鍵</td><td>支援</td></tr><tr><td>One Commander</td><td>支援</td><td>在檔案清單區域點擊中鍵</td><td>支援</td></tr><tr><td>Total Commander</td><td>支援</td><td>在檔案清單區域點擊中鍵</td><td>支援</td></tr><tr><td>XYplorer</td><td>支援</td><td>在檔案清單區域點擊中鍵</td><td>支援</td></tr></tbody></table><p>這五款都是透過比對執行中的處理程序來識別目標視窗的(其中 Directory Opus 和 Total Commander 還會透過它們各自公開文件記錄的 <code>WM_COPYDATA</code> 遠端控制介面通訊，而不是直接擷取畫面；Files 和 One Commander 沒有提供遠端控制通訊協定，因此改用 UI Automation)。</p><h2 id="應用程式自帶的對話方塊-可選外掛" tabindex="-1">應用程式自帶的對話方塊(可選外掛) <a class="header-anchor" href="#應用程式自帶的對話方塊-可選外掛" aria-label="Permalink to &quot;應用程式自帶的對話方塊(可選外掛)&quot;">​</a></h2><p>這幾項針對的是第三方應用程式裡的某一個特定對話方塊——而不是整個應用程式，跟上面內建的那幾個對話方塊是同一個思路。在<a href="./settings/plugins.html">設定 → 外掛</a>裡安裝/啟用，每個外掛只有一個元件，直接在那裡開關即可(沒有單獨的設定對話方塊，因為也沒有別的東西需要切換)。</p><table tabindex="0"><thead><tr><th>目標</th><th>內嵌搜尋</th><th>快速導覽</th><th>作用中路徑偵測</th></tr></thead><tbody><tr><td>WPS Office 的開啟/儲存對話方塊</td><td>支援</td><td>中鍵，或左鍵點擊內嵌視窗自帶的圖示</td><td>——</td></tr><tr><td>WinRAR 的解壓縮對話方塊</td><td>支援</td><td>中鍵，或左鍵點擊內嵌視窗自帶的圖示</td><td>——</td></tr><tr><td>Bandizip 的解壓縮對話方塊</td><td>支援</td><td>中鍵，或左鍵點擊內嵌視窗自帶的圖示</td><td>——</td></tr><tr><td>Bandizip 的新增檔案對話方塊</td><td>支援</td><td>中鍵，或左鍵點擊內嵌視窗自帶的圖示</td><td>——</td></tr></tbody></table><p>識別靠的是控制項結構而不是視窗標題，所以每款軟體不管裝的是哪種語言包都能正常運作。WPS 那一項涵蓋文字、表格、簡報和 PDF——它們用的是同一個對話方塊；WPS 不使用 Windows 內建的對話方塊，而是自繪了一個，這也正是它需要單獨一個外掛、而大多數程式被上面內建的那幾項涵蓋的原因。跟內建的那幾個一樣，作用中路徑偵測在這裡也沒有意義——Lertaro 已經嵌入對話方塊本身了，不存在另一個「其它視窗」可供它偵測並作為搜尋範圍。</p><hr><p>想為這裡沒有列出的檔案管理員開發自己的整合？參見開發手冊裡的<a href="./../dev-guide/sdk/system-adapters.html">系統與對話方塊轉接</a>參考文件。</p>',18)])])}const g=d(o,[["render",h]]);export{u as __pageData,g as default};
